queries.query:
INSERT INTO anuncio( titulo, conteudo, tipo_anuncio, botao_primario_texto, botao_primario_link, botao_secundario_texto, botao_secundario_link, imagem_url, imagem_alt, icone, ativo, autor_id)
VALUES( @Titulo, @Conteudo, @TipoAnuncio, @BotaoPrimarioTexto, @BotaoPrimarioLink, @BotaoSecundarioTexto, @BotaoSecundarioLink, @ImagemUrl, @ImagemAlt, @Icone, @Ativo, @AutorId)
RETURNING id;
